mapper.select:
SELECT *
FROM (

        SELECT

        FROM ${tableName}
        WHERE deleted = 0

            AND product_name LIKE CONCAT('%', #{productName}, '%')


            AND product_code LIKE CONCAT('%', #{productCode}, '%')


            AND (
                warehouse_name LIKE CONCAT('%', #{location}, '%')
                OR location_name LIKE CONCAT('%', #{location}, '%')
            )


            AND record_date >= #{startTime}


            AND record_date <= #{endTime}


) t
ORDER BY t.record_date ASC, t.record_id ASC

SELECT t.name AS name, SUM(t.stat_value) AS value
FROM (

        SELECT
            product_name AS name,


                    SUM(IFNULL(in_quantity, 0)) AS stat_value


                    SUM(IFNULL(out_quantity, 0)) AS stat_value


        FROM ${tableName}
        WHERE deleted = 0
          AND biz_type = #{bizType}

            AND record_date >= #{startTime}


            AND record_date <= #{endTime}

        GROUP BY product_name

) t
WHERE t.name IS NOT NULL
  AND t.name != ''
GROUP BY t.name
HAVING value > 0
ORDER BY value DESC
LIMIT #{limit}

SELECT t.name AS name, SUM(t.stat_value) AS value FROM (
SELECT
DATE_FORMAT(record_date, '%Y-%m') AS name,
DATE_FORMAT(record_date, '%Y-%m-%d') AS name,
SUM(IFNULL(in_quantity, 0)) AS stat_value
SUM(IFNULL(out_quantity, 0)) AS stat_value
FROM ${tableName} WHERE deleted = 0 AND biz_type = #{bizType}
AND record_date >= #{startTime}
AND record_date <= #{endTime}
GROUP BY
DATE_FORMAT(record_date, '%Y-%m')
DATE_FORMAT(record_date, '%Y-%m-%d')
) t GROUP BY t.name ORDER BY t.name ASC
